  "commands": [
    {
      "keystrokes": "df -h / /var /tmp /app 2>&1; echo '---'; du -sh /var/cache/apt 2>/dev/null; apt-get clean; rm -rf /var/cache/apt/archives/*.deb 2>/dev/null\n",
      "duration": 2
    }
  ]
}

